function attendanceAlerts(from,to){let rules=attendanceAlertRules(),alerts=[];active().forEach(p=>{let records=db.attendance.filter(a=>a.personId===p.id&&a.date>=from&&a.date<=to).sort((a,b)=>a.date.localeCompare(b.date)),byDate=new Map(records.map(r=>[r.date,r]));let late=records.filter(r=>shiftMetrics(p,r).lateMinutes>=Math.max(1,+rules.lateMinutes||30)),missing=records.filter(r=>{let m=shiftMetrics(p,r);return m.missingCheckIn||m.missingCheckOut}),work=records.filter(r=>['Present','Absent','Half Day'].includes(r.status)),attended=work.reduce((n,r)=>n+(r.status==='Present'?1:r.status==='Half Day'?.5:0),0),rate=work.length?attended/work.length*100:100,streak=0,maxStreak=0;for(let d=new Date(from+'T12:00:00'),end=new Date(to+'T12:00:00');d<=end;d.setDate(d.getDate()+1)){let date=d.toLocaleDateString('en-CA');if(!expectedWorkday(p,date))continue;let r=byDate.get(date);if(r?.status==='Absent'){streak++;maxStreak=Math.max(maxStreak,streak)}else streak=0}if(maxStreak>=(+rules.absenceStreak||2))alerts.push({level:'high',person:p,message:maxStreak+' consecutive scheduled absences',kind:'Absence streak'});if(late.length>=(+rules.lateOccurrences||3))alerts.push({level:'medium',person:p,message:late.length+' late arrivals of '+(+rules.lateMinutes||30)+'+ minutes',kind:'Repeated lateness'});if(missing.length)alerts.push({level:'medium',person:p,message:missing.length+' record(s) with missing check-in/out',kind:'Missing punches'});if(work.length>=5&&rate<(+rules.lowAttendance||85))alerts.push({level:'medium',person:p,message:Math.round(rate)+'% attendance across '+work.length+' marked workdays',kind:'Low attendance'})});return alerts.sort((a,b)=>(a.level==='high'?-1:1)-(b.level==='high'?-1:1))}
